// platform.toolpolicy.golden — cross-implementation contract evidence
// (Oracle 3): every verdict of the C++ port must match the Python canonical
// evaluator (paleo_workbench.mapping.tool_availability) on the golden matrix
// generated by make_golden.py from the main repository. enabled / visible /
// checked / disabled_reason are compared exactly, for every tool in every
// context. Any drift fails with the tool + field + both values.

#include <cstdio>

#include <QApplication>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>

#include <pwb/tool_policy/tool_availability.hpp>
#include <pwb/tool_policy/tool_context.hpp>

#include "test_fixtures.hpp"
#include "test_framework.hpp"

using pwb::tool_policy::ToolContextSnapshot;
using pwb::tool_policy::evaluate_tool;

namespace {

bool get_bool(const QJsonObject& object, const QString& key, bool fallback) {
    const QJsonValue value = object.value(key);
    return value.isBool() ? value.toBool() : fallback;
}

double get_double(const QJsonObject& object, const QString& key) {
    return object.value(key).toDouble(0.0);
}

int get_int(const QJsonObject& object, const QString& key) {
    return static_cast<int>(object.value(key).toDouble(0.0));
}

std::vector<std::string> get_string_list(const QJsonObject& object,
                                         const QString& key) {
    std::vector<std::string> out;
    const QJsonValue value = object.value(key);
    if (value.isArray()) {
        for (const QJsonValue entry : value.toArray())
            out.push_back(entry.toString().toStdString());
    } else if (value.isString() && !value.toString().isEmpty()) {
        out.push_back(value.toString().toStdString());
    }
    return out;
}

// Rebuilds the snapshot from the same JSON the Python generator encoded.
ToolContextSnapshot context_from_json(const QJsonObject& json) {
    ToolContextSnapshot ctx;
    ctx.project_open = get_bool(json, "project_open", true);
    ctx.qgis_available = get_bool(json, "qgis_available", false);
    ctx.native_canvas_available = get_bool(json, "native_canvas_available", false);
    ctx.backend_mode = json.value("backend_mode").toString("unknown").toStdString();
    ctx.backend_reason = json.value("backend_reason").toString().toStdString();
    ctx.blocking_task = json.value("blocking_task").toString().toStdString();
    const QJsonValue stage = json.value("mapping_stage");
    if (stage.isString()) ctx.mapping_stage = stage.toString().toStdString();
    ctx.write_granted = get_bool(json, "write_granted", false);
    ctx.active_layer_id = json.value("active_layer_id").toString().toStdString();
    ctx.active_layer_kind = json.value("active_layer_kind").toString().toStdString();
    ctx.layer_name = json.value("layer_name").toString().toStdString();
    ctx.layer_role = json.value("layer_role").toString().toStdString();
    ctx.layer_role_label = json.value("layer_role_label").toString().toStdString();
    ctx.layer_is_facies = get_bool(json, "layer_is_facies", false);
    ctx.artifact_maturity = json.value("artifact_maturity").toString().toStdString();
    ctx.layer_frozen = get_bool(json, "layer_frozen", false);
    ctx.layer_missing = get_bool(json, "layer_missing", false);
    ctx.layer_degraded = get_bool(json, "layer_degraded", false);
    ctx.qgis_layer_type = json.value("qgis_layer_type").toString().toStdString();
    ctx.vector_writable = get_bool(json, "vector_writable", false);
    ctx.editing = get_bool(json, "editing", false);
    ctx.dirty = get_bool(json, "dirty", false);
    const QJsonValue gate = json.value("edit_gate_open");
    if (gate.isBool()) ctx.edit_gate_open = gate.toBool();
    else if (gate.isNull() && json.contains("edit_gate_open"))
        ctx.edit_gate_open = std::nullopt;   // explicit unknown
    // Absent field keeps the Python dataclass default (true).
    ctx.edit_gate_reason = json.value("edit_gate_reason").toString().toStdString();
    ctx.raw_locked = get_bool(json, "raw_locked", false);
    ctx.stage_locked = get_bool(json, "stage_locked", false);
    ctx.can_undo = get_bool(json, "can_undo", false);
    ctx.can_redo = get_bool(json, "can_redo", false);
    ctx.selection_count = get_int(json, "selection_count");
    ctx.compatible_polygon_count = get_int(json, "compatible_polygon_count");
    ctx.topology_error_count = get_int(json, "topology_error_count");
    ctx.selection_multipart_count = get_int(json, "selection_multipart_count");
    ctx.split_ready = get_bool(json, "split_ready", false);
    ctx.merge_ready = get_bool(json, "merge_ready", false);
    ctx.reshape_ready = get_bool(json, "reshape_ready", false);
    ctx.collect_ready = get_bool(json, "collect_ready", false);
    ctx.snapping_available = get_bool(json, "snapping_available", true);
    ctx.snapping_enabled = get_bool(json, "snapping_enabled", false);
    ctx.topology_available = get_bool(json, "topology_available", true);
    ctx.topology_enabled = get_bool(json, "topology_enabled", false);
    ctx.avoid_intersections_enabled = get_bool(json, "avoid_intersections_enabled", true);
    ctx.tracing_enabled = get_bool(json, "tracing_enabled", false);
    ctx.vertex_all_layers = get_bool(json, "vertex_all_layers", true);
    ctx.crs_valid = get_bool(json, "crs_valid", true);
    ctx.scale_denominator = get_double(json, "scale_denominator");
    ctx.provider_name = json.value("provider_name").toString().toStdString();
    const QJsonValue provider = json.value("provider_writable");
    if (provider.isBool()) ctx.provider_writable = provider.toBool();
    else if (json.contains("provider_writable")) ctx.provider_writable = std::nullopt;
    ctx.provider_writable_approximate =
        get_bool(json, "provider_writable_approximate", false);
    ctx.current_tool = json.value("current_tool").toString("pan").toStdString();
    ctx.capability_flags = get_string_list(json, "capability_flags");
    ctx.queryable_layer_count = get_int(json, "queryable_layer_count");
    ctx.can_previous_extent = get_bool(json, "can_previous_extent", false);
    ctx.can_next_extent = get_bool(json, "can_next_extent", false);
    return ctx;
}

}  // namespace

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    const QString golden_path =
        pwb::test_fixtures::test_data_path(QStringLiteral("golden_tool_policy.json"));
    QFile file(golden_path);
    PWB_CHECK_MSG(file.open(QIODevice::ReadOnly),
                  "cannot open golden file: " + golden_path.toStdString());
    const QJsonDocument document = QJsonDocument::fromJson(file.readAll());
    PWB_CHECK(document.isObject());
    const QJsonObject root = document.object();
    const QJsonObject contexts = root.value("contexts").toObject();
    const QJsonObject expectations = root.value("expectations").toObject();

    int compared = 0;
    int mismatches = 0;
    for (auto ctx_it = expectations.begin(); ctx_it != expectations.end(); ++ctx_it) {
        const QJsonObject fields = contexts.value(ctx_it.key()).toObject();
        PWB_CHECK_MSG(!fields.isEmpty(),
                      "golden context fields missing: " + ctx_it.key().toStdString());
        const ToolContextSnapshot ctx = context_from_json(fields);
        const QJsonObject tools = ctx_it.value().toObject();
        for (auto tool_it = tools.begin(); tool_it != tools.end(); ++tool_it) {
            const std::string tool_id = tool_it.key().toStdString();
            const QJsonObject expected = tool_it.value().toObject();
            const auto verdict = evaluate_tool(tool_id, ctx);
            const bool visible_ok =
                verdict.visible == expected.value("visible").toBool();
            const bool enabled_ok =
                verdict.enabled == expected.value("enabled").toBool();
            const bool checked_ok =
                verdict.checked == expected.value("checked").toBool();
            const bool reason_ok = verdict.disabled_reason
                == expected.value("disabled_reason").toString().toStdString();
            ++compared;
            if (!visible_ok || !enabled_ok || !checked_ok || !reason_ok) {
                ++mismatches;
                std::fprintf(stderr,
                             "MISMATCH ctx=%s tool=%s cpp(v=%d,e=%d,c=%d,r='%s') "
                             "py(v=%d,e=%d,c=%d,r='%s')\n",
                             ctx_it.key().toUtf8().constData(),
                             tool_it.key().toUtf8().constData(),
                             verdict.visible, verdict.enabled, verdict.checked,
                             verdict.disabled_reason.c_str(),
                             expected.value("visible").toBool(),
                             expected.value("enabled").toBool(),
                             expected.value("checked").toBool(),
                             expected.value("disabled_reason")
                                 .toString().toUtf8().constData());
            }
        }
    }
    std::printf("golden parity: %d verdicts compared, %d mismatches\n",
                compared, mismatches);
    PWB_CHECK(mismatches == 0);
    return ::pwb::test::report("platform.toolpolicy.golden");
}
